CREATE TABLE users(id uuid PRIMARY KEY,email varchar(254) NOT NULL UNIQUE,password_hash varchar(100) NOT NULL,account_status varchar(30) NOT NULL DEFAULT 'ACTIVE',email_verified_at timestamptz,admin_totp varchar(128),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles(user_id uuid NOT NULL REFERENCES users,role varchar(20) NOT NULL CHECK(role IN ('CLIENT','DEVELOPER','ADMIN')),PRIMARY KEY(user_id,role));
CREATE TABLE developer_profiles(user_id uuid PRIMARY KEY REFERENCES users,slug varchar(120) UNIQUE NOT NULL,display_name varchar(100) NOT NULL DEFAULT '',headline varchar(160) NOT NULL DEFAULT '',bio text NOT NULL DEFAULT '',technology varchar(300) NOT NULL DEFAULT '',category varchar(200) NOT NULL DEFAULT '',availability_status varchar(30) NOT NULL DEFAULT 'NOT_ACCEPTING',booked_until date,github_url text,linkedin_url text,approval_status varchar(30) NOT NULL DEFAULT 'DRAFT',moderation_reason text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE showcase_entitlements(user_id uuid PRIMARY KEY REFERENCES users,active_slot_limit int NOT NULL DEFAULT 3 CHECK(active_slot_limit>=0),source varchar(20) NOT NULL DEFAULT 'FREE');
CREATE TABLE products(id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES users,slug varchar(180) UNIQUE NOT NULL,title varchar(120) NOT NULL,summary varchar(240) NOT NULL,description text NOT NULL,project_type varchar(40) NOT NULL,category varchar(100) NOT NULL,technology varchar(300) NOT NULL,visibility varchar(30) NOT NULL DEFAULT 'PUBLIC',contribution_text text NOT NULL,available_for_similar_work boolean NOT NULL DEFAULT true,approval_status varchar(30) NOT NULL DEFAULT 'DRAFT',lifecycle_status varchar(30) NOT NULL DEFAULT 'DRAFT',live_url text,video_url text,moderation_reason text,rights_confirmed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_owner ON products(owner_user_id,lifecycle_status);
CREATE INDEX products_discovery ON products(approval_status,lifecycle_status,visibility,updated_at DESC);
CREATE INDEX products_search ON products USING gin(to_tsvector('english',title||' '||summary||' '||description||' '||category||' '||technology));
CREATE TABLE product_media(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES products,storage_key text NOT NULL UNIQUE,content_type varchar(50) NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>0 AND size_bytes<=5242880),alt_text varchar(300) NOT NULL DEFAULT '',verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE saved_products(user_id uuid REFERENCES users,product_id uuid REFERENCES products,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
CREATE TABLE inquiries(id uuid PRIMARY KEY,reference_product_id uuid NOT NULL REFERENCES products,developer_user_id uuid NOT NULL REFERENCES users,client_email varchar(254) NOT NULL,client_name varchar(100) NOT NULL,company_name varchar(150),request_type varchar(30) NOT NULL,description text NOT NULL,budget_band varchar(40) NOT NULL,timeline_band varchar(40) NOT NULL,current_status varchar(50) NOT NULL DEFAULT 'CREATED_UNVERIFIED',email_confirmed_at timestamptz,idempotency_key uuid NOT NULL UNIQUE,request_hash varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX inquiries_developer ON inquiries(developer_user_id,created_at DESC);
CREATE INDEX inquiries_client ON inquiries(client_email);
CREATE TABLE inquiry_events(id uuid PRIMARY KEY,inquiry_id uuid NOT NULL REFERENCES inquiries,event_type varchar(60) NOT NULL,actor_id uuid,actor_type varchar(30) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews(id uuid PRIMARY KEY,inquiry_id uuid NOT NULL UNIQUE REFERENCES inquiries,developer_user_id uuid NOT NULL REFERENCES users,rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5),review_text text NOT NULL,visibility varchar(20) NOT NULL DEFAULT 'ANONYMOUS',moderation_status varchar(30) NOT NULL DEFAULT 'HELD_FOR_REVIEW',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash varchar(64) PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,expires_at timestamptz NOT NULL,mfa_verified boolean NOT NULL DEFAULT false);
CREATE TABLE account_tokens(id uuid PRIMARY KEY,token_hash varchar(64) UNIQUE NOT NULL,kind varchar(40) NOT NULL,user_id uuid REFERENCES users,inquiry_id uuid REFERENCES inquiries,email varchar(254) NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE email_outbox(id uuid PRIMARY KEY,recipient varchar(254) NOT NULL,subject varchar(200) NOT NULL,body text NOT NULL,attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON email_outbox(next_attempt_at) WHERE sent_at IS NULL;
CREATE TABLE reports(id uuid PRIMARY KEY,reporter_id uuid REFERENCES users,target_type varchar(30) NOT NULL,target_id uuid NOT NULL,reason varchar(40) NOT NULL,detail text NOT NULL,status varchar(30) NOT NULL DEFAULT 'OPEN',resolution text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_actions(id uuid PRIMARY KEY,admin_id uuid NOT NULL REFERENCES users,target_type varchar(30) NOT NULL,target_id uuid NOT NULL,action varchar(40) NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,title varchar(200) NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE analytics_events(id uuid PRIMARY KEY,event_name varchar(60) NOT NULL,entity_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_buckets(bucket varchar(128) PRIMARY KEY,hits int NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE categories(slug varchar(100) PRIMARY KEY,name varchar(100) UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE technologies(slug varchar(100) PRIMARY KEY,name varchar(100) UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true);
INSERT INTO categories(slug,name) VALUES ('inventory','Inventory'),('booking','Booking'),('restaurants','Restaurants'),('crm','CRM'),('education','Education'),('productivity','Productivity'),('ecommerce','E-commerce'),('healthcare','Healthcare'),('fintech','FinTech'),('ai-automation','AI Automation'),('developer-tools','Developer Tools');
INSERT INTO technologies(slug,name) VALUES ('react','React'),('nextjs','Next.js'),('vue','Vue'),('spring-boot','Spring Boot'),('postgresql','PostgreSQL'),('flutter','Flutter');
CREATE TABLE legal_acceptances(user_id uuid NOT NULL REFERENCES users,document_version varchar(30) NOT NULL,accepted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,document_version));
CREATE TABLE deletion_requests(user_id uuid PRIMARY KEY REFERENCES users,status varchar(30) NOT NULL DEFAULT 'PENDING',created_at timestamptz NOT NULL DEFAULT now());
